UPDATE researchers SET description = 'Possui graduação em Licenciatura em Matemática pela Universidade Estadual de Feira de Santana (2001), mestrado em Matemática pela Universidade Federal da Bahia (2003) e doutorado em Geofísica Aplicada pela Universidade Federal da Bahia (2009). Atualmente é professor titular na Universidade Federal da Bahia. Tem experiência na área de modelagem em meios porosos, atuando principalmente nos seguintes temas: métodos numéricos e modelagem com parâmetros de incerteza.' WHERE id = 'e288b7c5-ffb1-404b-a952-783cc2fb0967';